mapper.select:
SELECT b.item_id AS item_id, i.item_code AS item_code, i.item_name AS item_name, i.unit AS unit, b.batch_no AS batch_no, s.warehouse_id AS warehouse_id, w.warehouse_name AS warehouse_name, b.production_date AS production_date, b.expiry_date AS expiry_date, (b.expiry_date - CURRENT_DATE) AS "daysLeft", s.quantity AS quantity, (s.quantity - s.pre_allocated_qty) AS "availableQty" FROM batch b JOIN item i ON i.id = b.item_id JOIN stock s ON s.batch_id = b.id JOIN warehouse w ON w.id = s.warehouse_id WHERE b.expiry_date IS NOT NULL AND b.expiry_date <= CURRENT_DATE + #{alertDays} AND s.quantity > 0
AND s.warehouse_id = #{query.warehouseId}
AND b.item_id = #{query.itemId}
ORDER BY b.expiry_date ASC, s.id ASC
